// Extraer y enriquecer contexto del usuario, catálogo y su Gamer DNA
const inputData = $input.first().json.body || $input.first().json;

const userId = inputData.user_id || inputData.userId || 'anonymous';
const message = inputData.message || '';
const sessionId = inputData.session_id || inputData.sessionId || '';
const topic = inputData.topic || 'Recomendaciones';

const userProfile = inputData.user_profile || {};
const rawDna = userProfile.gamer_dna || inputData.gamerDna || {
  exploration: 25,
  competitive: 25,
  collection: 25,
  narrative: 25
};

const dnaArray = [
  { name: 'Explorador', val: rawDna.exploration || 0 },
  { name: 'Competitivo', val: rawDna.competitive || 0 },
  { name: 'Coleccionista', val: rawDna.collection || 0 },
  { name: 'Narrativo', val: rawDna.narrative || 0 }
];
const dominantArchetype = rawDna.dominantArchetype || dnaArray.reduce((prev, curr) => (curr.val > prev.val ? curr : prev)).name;

const ownedGames = inputData.owned_games || [];
const userOwnedGameIds = Array.isArray(inputData.userOwnedGameIds)
  ? inputData.userOwnedGameIds
  : ownedGames.map(g => g.id);

const catalog = inputData.available_games_catalog || [];
const catalogSummary = catalog.length > 0
  ? catalog.map(g => `[ID: ${g.id}] "${g.title}" - Géneros: ${Array.isArray(g.categories) ? g.categories.join(', ') : (g.categories || 'Acción')} - Precio: Bs. ${g.final_price || g.base_price}`).join('\n')
  : '[ID: 1] "Neon Odyssey: Cyber Genesis" - Géneros: Acción, RPG, Sci-Fi - Precio: Bs. 90\n[ID: 2] "Shadows of Eldoria" - Géneros: RPG, Aventura - Precio: Bs. 127.5';

const systemPrompt = `Eres ViniChat, el copiloto gamer y asistente de inteligencia artificial oficial de la plataforma de videojuegos ViniGames (UTEPSA 2026).

INFORMACIÓN DEL USUARIO:
- Arquetipo dominante Gamer DNA: ${dominantArchetype}
- Distribución ADN: Exploración (${rawDna.exploration || 25}%), Competitivo (${rawDna.competitive || 25}%), Colección (${rawDna.collection || 25}%), Narrativo (${rawDna.narrative || 25}%)
- Videojuegos que el usuario YA POSEE en su biblioteca (NO recomendárselos): [${userOwnedGameIds.join(', ')}]

CATÁLOGO DISPONIBLE EN LA TIENDA:
${catalogSummary}

REGLAS DE RESPUESTA:
1. Responde siempre con tono amigable, entusiasta, gamer y estructurado usando Markdown (negritas, emojis, listas).
2. Si el usuario solicita recomendaciones o consejos de compra, sugiere hasta 3 títulos del catálogo disponible afines a su consulta y a su Gamer DNA.
3. OBLIGATORIO: Debes responder ÚNICAMENTE en formato JSON válido con las claves:
{
  "reply": "Tu respuesta conversacional en formato Markdown...",
  "recommended_game_ids": [array de enteros con los IDs de los juegos recomendados],
  "topic_detected": "Categoría del mensaje"
}`;

return {
  userId,
  message,
  sessionId,
  topic,
  gamerDna: { ...rawDna, dominantArchetype },
  userOwnedGameIds,
  systemPrompt
};
